shots.draw_js:
clearScene();setBig(null);setEq(null);
note("线性做不得",400,300,"r lg");
note("那最好能到多好",880,300,"y lg");
note("先问上限，再去找算法",640,400,"sm lg");
setCap("批评完三个做法，该问一句：<b>理论上限本来是多少</b>？");

clearScene();setEq(null);
setBig("前期探索完就一直贪心","这样遗憾应该是常数");
setCap("<b>常数遗憾做不到</b>。任何算法都会被一对足够接近的臂骗到。");

clearScene();setBig(null);
setEq("$$\\liminf_{T\\to\\infty}\\frac{\\mathrm{Regret}(T)}{\\log T}\\ \\ge\\ \\sum_{a:\\,\\Delta_a>0}\\frac{\\Delta_a}{KL(R_a\\,\\|\\,R_{a^*})}\\,$$","top");
note("差距在分子",420,330,"b lg");
note("可区分度在分母",880,330,"v lg");
setCap("Lai–Robbins 下界：遗憾至少<b>随 log T 增长</b>，系数由差距和 KL 决定。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2,3],step:420,vals:[2.43,4.97,9.98,24.99],
  x:330,y:410,w:620,h:150,max:28,
  label:function(i){return ["Δ=.20","Δ=.10","Δ=.05","Δ=.02"][i];},
  cls:function(i){return i>=2?"r":"y";},
  fmt:function(v){return v.toFixed(2);}});
note("下界系数 Δ/KL",640,452,"sm");
setCap("差距<b>减半</b>，下界系数就<b>翻倍</b> —— 越接近的臂越难分开。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:290,items:[
  {label:"常数遗憾",sub:"被排除",state:"dead"},
  {label:"线性遗憾",sub:"太差",state:"dead"},
  {label:"log T",sub:"值得去追",state:"on"}]});
note("下界在指路",640,420,"y");
setCap("<b>指名反驳</b>：常数做不到；但 <b>log T 没被禁止</b> —— 于是值得去找。");

clearScene();setBig(null);setEq(null);
note("乐观面对不确定",640,290,"y lg");
note("整个算法就这一句",640,370,"sm lg");
setCap("下界说 log T 可以争取。这一集的想法<b>只有一句话</b>。");

clearScene();setEq(null);
setBig("拉均值最高的臂","用最好的估计做决定，这才理性");
setCap("点估计<b>扔掉了</b>「我有多不确定」—— 而那恰恰是该用来决策的信息。");

clearScene();setBig(null);
setEq("$$a_t=\\arg\\max_a\\ \\big[\\hat{Q}_t(a)+u_t(a)\\big]$$","top");
note("点估计",470,330,"b lg");
note("不确定的半径",840,330,"v lg");
setCap("规则：拉 <b>估计 + 半径</b> 最大的臂 —— 拉过越少的臂，半径越宽。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:330,items:[
  {label:"乐观拉一下",sub:"两种结局",state:"on"},
  {label:"它真好",sub:"不亏",state:"on"},
  {label:"它不好",sub:"界会收缩",state:"on"}]});
note("两难都赢",640,410,"y");
setCap("<b>为什么这一句就够</b>：乐观的拉动只有两种结局，<b>两种都可以接受</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:290,items:[
  {label:"贪心",sub:"错误不自限",state:"dead"},
  {label:"固定 ε",sub:"探索不收缩",state:"dead"},
  {label:"乐观",sub:"两者都解决",state:"on"}]});
note("不确定性当理由，不当噪声",640,420,"y");
setCap("<b>指名反驳</b>：别拉均值最高的。<b>不确定性是决策依据，不是待消除的噪声</b>。");

clearScene();setBig(null);setEq(null);
note("半径该多宽",640,290,"y lg");
note("宽了太保守，窄了会骗自己",640,370,"sm lg");
setCap("规则依赖那个半径。<b>它不能随便定</b> —— 整个保证都挂在它上面。");

clearScene();setEq(null);
setBig("±1.96 σ/√n","标准的 95% 置信区间");
setCap("σ <b>是未知的</b> —— 它就是我们要估的那个分布的方差。");

clearScene();setBig(null);
setEq("$$P\\big(Q(a)>\\hat{Q}_t(a)+u\\big)\\ \\le\\ e^{-2nu^2}$$","top");
note("只要奖励有界",420,330,"g lg");
note("不需要知道方差",880,330,"g lg");
setCap("Hoeffding：<b>只要奖励落在 [0,1]</b>，对<b>任意 n</b> 都成立。");

clearScene();setBig(null);
setEq("$$e^{-2nu^2}=\\frac{\\delta}{t^2}\\ \\Longrightarrow\\ u_t(a)=\\sqrt{\\frac{\\log\\!\\big(t^2/\\delta\\big)}{2\\,n_t(a)}}$$","top");
note("先定失败预算，再反解半径",640,330,"y lg");
setCap("<b>反着用</b>：先说「我允许它以多大概率失败」，再解出半径。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1],step:760,vals:[0.2470,0.0980],
  x:400,y:410,w:480,h:150,max:0.30,
  label:function(i){return ["Hoeffding","正态近似"][i];},
  cls:function(i){return i===0?"g":"r";},
  fmt:function(v){return v.toFixed(4);}});
note("n=100 时的半径",640,452,"sm");
setCap("<b>指名反驳</b>：不用 σ，用<b>有界性</b>。宽 2.5 倍 —— 而那正是<b>保证的价格</b>。");
